import{_ as o,o as c,c as a,an as d}from"./chunks/framework.BrMtPKZw.js";const _=JSON.parse('{"title":"API 参考","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api.md","filePath":"zh/api.md","lastUpdated":null}'),t={name:"zh/api.md"};function i(r,e,n,l,p,s){return c(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="API-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#API-参考" aria-label="Permalink to &quot;API 参考 {#API-参考}&quot;">​</a></h1><p>本页概览 <code>Parking</code> 的公开 API。下面列出的所有符号均由本包导出。</p><blockquote><p>说明：本包的函数签名与详细文档（docstring）目前为英文，与代码中的注释保持一致， 因此逐符号的自动生成 API 文档统一在英文 <a href="./api">API Reference</a> 页面生成。 本节按主题给出中文说明，并列出对应符号名称，便于对照查阅。</p></blockquote><h2 id="车辆与几何" tabindex="-1">车辆与几何 <a class="header-anchor" href="#车辆与几何" aria-label="Permalink to &quot;车辆与几何 {#车辆与几何}&quot;">​</a></h2><p>涉及车辆位形与几何的符号：<code>Vehicle</code>、<code>Pose</code>、<code>Rectangle</code>、<code>corners</code>、<code>footprint</code>、<code>rear_axle_pose</code>。 详细签名与说明见英文 <a href="./api">API Reference</a>。</p><h2 id="环境与车位" tabindex="-1">环境与车位 <a class="header-anchor" href="#环境与车位" aria-label="Permalink to &quot;环境与车位 {#环境与车位}&quot;">​</a></h2><p>符号：<code>ParkingSpot</code>、<code>spot_corners</code>、<code>Environment</code>、<code>inflate_rect</code>、<code>with_clearance</code>、<code>build_lot</code>。 见英文 <a href="./api">API Reference</a> 对应小节。</p><h2 id="碰撞检测" tabindex="-1">碰撞检测 <a class="header-anchor" href="#碰撞检测" aria-label="Permalink to &quot;碰撞检测 {#碰撞检测}&quot;">​</a></h2><p>符号：<code>is_collision</code>、<code>collision_reason</code>、<code>path_clear</code>。 见英文 <a href="./api">API Reference</a>。</p><h2 id="规划" tabindex="-1">规划 <a class="header-anchor" href="#规划" aria-label="Permalink to &quot;规划 {#规划}&quot;">​</a></h2><p>符号：<code>PlanResult</code>、<code>step_vehicle</code>、<code>plan_park</code>、<code>plan_leave</code>。 见英文 <a href="./api">API Reference</a>。</p><p>规划结果通过 <code>PlanResult</code> 返回。其 <code>status</code> 字段为下列 <code>PlanStatus</code> 之一： <code>SUCCESS</code>、<code>NO_PATH_FOUND</code>、<code>START_IN_COLLISION</code> 或 <code>GOAL_IN_COLLISION</code>。 <code>reason</code> 字段包含对结果的可读描述，例如 <code>&quot;start pose is in collision (not in a valid free space)&quot;</code>。</p><h2 id="仿真与路径细化" tabindex="-1">仿真与路径细化 <a class="header-anchor" href="#仿真与路径细化" aria-label="Permalink to &quot;仿真与路径细化 {#仿真与路径细化}&quot;">​</a></h2><p>符号：<code>simulate</code>、<code>refine_path</code>、<code>Trajectory</code>、<code>duration</code>、<code>trajectory</code>。 见英文 <a href="./api">API Reference</a>。</p><h2 id="可视化" tabindex="-1">可视化 <a class="header-anchor" href="#可视化" aria-label="Permalink to &quot;可视化 {#可视化}&quot;">​</a></h2><p>绘图与动画由可选的扩展包提供，以保持核心包轻量：</p><ul><li><p><code>ParkingPlots</code> - 当 <code>Plots</code> 在作用域中时自动加载，提供 <code>plot_scene</code>、<code>plot_pose!</code>、<code>plot_path!</code> 与 <code>animate_parking</code>。</p></li><li><p><code>ParkingMakie</code> - 当 <code>Makie</code>、<code>Bonito</code>、<code>WGLMakie</code> 在作用域中时自动加载，提供 <code>plot_scene!</code>、<code>makie_scene</code>、交互式 <code>designer</code>，并为 Makie <code>Axis</code> 实现 <code>plot_pose!</code> / <code>plot_path!</code>。</p></li></ul><p><code>plot_pose!</code> 与 <code>plot_path!</code> 与后端无关：其 <code>target</code> 为 <code>Plots.Plot</code>（Plots 后端）或 Makie <code>Axis</code>（Makie 后端）。 调用前请加载对应后端，例如 <code>using Parking, Plots</code> 或 <code>using Parking, Makie, Bonito, WGLMakie</code>。</p><p>符号：<code>plot_scene</code>、<code>plot_scene!</code>、<code>plot_pose!</code>、<code>plot_path!</code>、<code>makie_scene</code>、<code>animate_parking</code>、<code>designer</code>。 见英文 <a href="./api">API Reference</a>。</p>',19)])])}const P=o(t,[["render",i]]);export{_ as __pageData,P as default};
